// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.consolidationimport android.content.Contextimport androidx.work.CoroutineWorkerimport androidx.work.WorkerParametersimport timber.log.Timber/** * NOUS — Dream Mode Worker (Module 3 v2 — audit P0). * * Strategy §3.7: "Memory consolidation ('Dream Mode') — runs when device * charging + idle; extracts semantic facts from episodic memories using * local LLM; applies forgetting curve (confidence halved if not recalled * in 7 days)." * * This Worker is scheduled by [DreamModeScheduler] with constraints: *  - Device charging *  - Device idle *  - Network not required (local LLM) *  - Runs nightly between 2-4 AM * * ## Bridge pattern * * Workers can't use Hilt constructor injection (instantiated via reflection). * [DreamModeBridge] is set by [com.roshan.persona.memory.di.MemoryModule] at * app startup — same pattern as `SosLocationWorkerBridge` in Module 11. * * @see ConsolidationEngine */class DreamModeWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    override suspend fun doWork(): Result {        val engine = DreamModeBridge.consolidationEngine        if (engine == null) {            Timber.tag(TAG).w("ConsolidationEngine not available — retrying.")            return Result.retry()        }        return try {            Timber.tag(TAG).i("Dream Mode: starting consolidation cycle.")            val result = engine.runFullConsolidation()            Timber.tag(TAG).i("Dream Mode complete: $result")            Result.success()        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Dream Mode failed — retrying.")            Result.retry()        }    }    companion object {        private const val TAG = "DreamModeWorker"        const val UNIQUE_WORK_NAME = "nous_dream_mode"    }}/** * Static bridge for [DreamModeWorker] to access the Hilt-provided * [ConsolidationEngine]. Set by [com.roshan.persona.memory.di.MemoryModule] * at app startup. */object DreamModeBridge {    @Volatile    var consolidationEngine: ConsolidationEngine? = null}